-- Generated from db/imports/official/portals/portals.official.json and official map identities.
-- These are resource graph links, not verified gameplay trigger coordinates; all remain disabled.
CREATE TABLE IF NOT EXISTS `god2_game`.`portal_resource_links` (
    `portal_link_id` varchar(191) NOT NULL,
    `portal_id` bigint NULL,
    `client_build_id` varchar(64) NOT NULL,
    `source_resource_key` varchar(512) NOT NULL,
    `destination_resource_key` varchar(512) NOT NULL,
    `source_map_id` bigint NOT NULL,
    `destination_map_id` bigint NULL,
    `can_relative_path` varchar(512) NOT NULL,
    `can_record_index` int NOT NULL,
    `can_record_type` tinyint unsigned NOT NULL,
    `source_sha256` char(64) NOT NULL,
    `identity_evidence_status` varchar(30) NOT NULL,
    `source_coordinate_evidence_status` varchar(30) NOT NULL DEFAULT 'Unknown',
    `destination_coordinate_evidence_status` varchar(30) NOT NULL DEFAULT 'Unknown',
    `trigger_evidence_status` varchar(30) NOT NULL DEFAULT 'Unknown',
    `enabled` tinyint(1) NOT NULL DEFAULT 0,
    PRIMARY KEY (`portal_link_id`),
    UNIQUE KEY `ux_portal_resource_links_portal` (`portal_id`),
    KEY `ix_portal_resource_links_source` (`source_resource_key`),
    KEY `ix_portal_resource_links_destination` (`destination_resource_key`),
    CONSTRAINT `fk_portal_resource_links_portal` FOREIGN KEY (`portal_id`) REFERENCES `god2_game`.`portals` (`portal_id`),
    CONSTRAINT `fk_portal_resource_links_source_resource` FOREIGN KEY (`source_resource_key`) REFERENCES `god2_game`.`client_map_resources` (`resource_key`),
    CONSTRAINT `fk_portal_resource_links_destination_resource` FOREIGN KEY (`destination_resource_key`) REFERENCES `god2_game`.`client_map_resources` (`resource_key`),
    CONSTRAINT `fk_portal_resource_links_source_map` FOREIGN KEY (`source_map_id`) REFERENCES `god2_game`.`maps` (`map_id`),
    CONSTRAINT `fk_portal_resource_links_destination_map` FOREIGN KEY (`destination_map_id`) REFERENCES `god2_game`.`maps` (`map_id`),
    CONSTRAINT `ck_portal_resource_links_enabled` CHECK (`enabled`=0 OR (`identity_evidence_status` IN ('Verified','Derived') AND `source_coordinate_evidence_status` IN ('Verified','Derived') AND `destination_coordinate_evidence_status` IN ('Verified','Derived') AND `trigger_evidence_status` IN ('Verified','Derived')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

