UPDATE `god2_game`.`portal_resource_links` link_row
JOIN `god2_game`.`portals` portal_row ON portal_row.`name_zh_tw`=link_row.`portal_link_id`
SET link_row.`portal_id`=portal_row.`portal_id`;

UPDATE `god2_game`.`portals` portal_row
JOIN `god2_game`.`portal_resource_links` link_row ON link_row.`portal_id`=portal_row.`portal_id`
SET portal_row.`source_map_id`=link_row.`source_map_id`,portal_row.`destination_map_id`=link_row.`destination_map_id`,
    portal_row.`source_x`=NULL,portal_row.`source_y`=NULL,portal_row.`source_radius`=NULL,
    portal_row.`destination_x`=NULL,portal_row.`destination_y`=NULL,portal_row.`client_build_id`=link_row.`client_build_id`,
    portal_row.`evidence_source_type`='ClientResource',portal_row.`identity_evidence_status`=link_row.`identity_evidence_status`,
    portal_row.`source_coordinate_evidence_status`='Unknown',portal_row.`destination_coordinate_evidence_status`='Unknown',portal_row.`trigger_evidence_status`='Unknown',
    portal_row.`source_reference`=CONCAT('db/imports/official/portals/portals.official.json#',link_row.`portal_link_id`),
    portal_row.`source_sha256`=link_row.`source_sha256`,portal_row.`enabled`=0,
    portal_row.`admin_note`='CAN resource relation mapped to official client map identities; trigger and coordinates remain evidence-blocked.';

